theme.stylesheet:
/* Catppuccin Mocha — restrained Dynamic Theme overrides
   Typography default: IBM Plex Sans
   Install the font locally for Dark Reader's font override to work reliably. */

:root {
    color-scheme: dark !important;

    --ctp-rosewater: #f5e0dc;
    --ctp-flamingo: #f2cdcd;
    --ctp-pink: #f5c2e7;
    --ctp-mauve: #cba6f7;
    --ctp-red: #f38ba8;
    --ctp-maroon: #eba0ac;
    --ctp-peach: #fab387;
    --ctp-yellow: #f9e2af;
    --ctp-green: #a6e3a1;
    --ctp-teal: #94e2d5;
    --ctp-sky: #89dceb;
    --ctp-sapphire: #74c7ec;
    --ctp-blue: #89b4fa;
    --ctp-lavender: #b4befe;
    --ctp-text: #cdd6f4;
    --ctp-subtext1: #bac2de;
    --ctp-subtext0: #a6adc8;
    --ctp-overlay2: #9399b2;
    --ctp-overlay1: #7f849c;
    --ctp-overlay0: #6c7086;
    --ctp-surface2: #585b70;
    --ctp-surface1: #45475a;
    --ctp-surface0: #313244;
    --ctp-base: #1e1e2e;
    --ctp-mantle: #181825;
    --ctp-crust: #11111b;
}

/*
 * Do not globally recolor generic div/span elements here.
 * Dark Reader's dynamic engine remains responsible for preserving
 * site hierarchy while these rules pin high-value UI accents to Mocha.
 */

/* Links */
a:link {
    color: var(--ctp-blue) !important;
}
a:visited {
    color: var(--ctp-mauve) !important;
}
a:hover,
a:focus-visible {
    color: var(--ctp-sapphire) !important;
}

/* Selection + focus */
::selection {
    background: var(--ctp-surface2) !important;
    color: var(--ctp-text) !important;
}
::-moz-selection {
    background: var(--ctp-surface2) !important;
    color: var(--ctp-text) !important;
}
:focus-visible {
    outline-color: var(--ctp-mauve) !important;
}

/* Native controls */
input,
textarea,
select,
button {
    border-color: var(--ctp-surface1) !important;
}
input::placeholder,
textarea::placeholder {
    color: var(--ctp-overlay1) !important;
    opacity: 1 !important;
}
input[type="checkbox"],
input[type="radio"],
input[type="range"],
progress {
    accent-color: var(--ctp-mauve) !important;
}

/* Structural UI */
hr,
fieldset,
table,
th,
td {
    border-color: var(--ctp-surface1) !important;
}
blockquote {
    border-color: var(--ctp-mauve) !important;
}
dialog {
    border-color: var(--ctp-surface1) !important;
}

/* Semantic accents */
mark {
    background: var(--ctp-yellow) !important;
    color: var(--ctp-crust) !important;
}
ins {
    color: var(--ctp-green) !important;
}
del {
    color: var(--ctp-red) !important;
}

/* Code remains visually distinct without flattening the whole site. */
pre,
code,
kbd,
samp {
    border-color: var(--ctp-surface0) !important;
}
kbd {
    border-color: var(--ctp-surface2) !important;
}

/* Mocha scrollbars */
* {
    scrollbar-color: var(--ctp-surface2) var(--ctp-mantle);
}
::-webkit-scrollbar {
    background: var(--ctp-mantle) !important;
}
::-webkit-scrollbar-track {
    background: var(--ctp-mantle) !important;
}
::-webkit-scrollbar-thumb {
    background: var(--ctp-surface2) !important;
    border-color: var(--ctp-mantle) !important;
}
::-webkit-scrollbar-thumb:hover {
    background: var(--ctp-overlay0) !important;
}

/* Code typography — Fira Code
   Fira Code must be installed/available locally.
   Ligatures are explicitly enabled for code-like elements. */
code,
pre,
kbd,
samp,
tt {
    font-family: "Fira Code", "IBM Plex Mono", monospace !important;
    font-variant-ligatures: contextual common-ligatures !important;
    font-feature-settings: "calt" 1, "liga" 1 !important;
}

pre code {
    font-family: inherit !important;
}

/* Common syntax-highlight/editor containers that inherit correctly
   without replacing a site's syntax colors. */
.highlight,
.highlighter-rouge,
.sourceCode,
[class*="language-"],
[class*="lang-"] {
    font-family: "Fira Code", "IBM Plex Mono", monospace !important;
    font-variant-ligatures: contextual common-ligatures !important;
    font-feature-settings: "calt" 1, "liga" 1 !important;
}
